#include <ctype.h>
#include <errno.h>
#include <stdlib.h>

enum port_error { PORT_OK = 0, PORT_EMPTY, PORT_NOT_A_NUMBER, PORT_OUT_OF_RANGE };

enum port_error parse_port(const char *text, int *out)
{
    while (isspace((unsigned char)*text)) text++;
    if (*text == '\0') return PORT_EMPTY;
    if (!isdigit((unsigned char)*text)) return PORT_NOT_A_NUMBER;
    char *end;
    errno = 0;
    long v = strtol(text, &end, 10);
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0') return PORT_NOT_A_NUMBER;
    if (errno == ERANGE || v < 1 || v > 65535) return PORT_OUT_OF_RANGE;
    *out = (int)v;
    return PORT_OK;
}

const char *port_error_text(enum port_error e)
{
    switch (e)
    {
    case PORT_OK: return "ok";
    case PORT_EMPTY: return "empty";
    case PORT_NOT_A_NUMBER: return "not a number";
    case PORT_OUT_OF_RANGE: return "out of range";
    }
    return "unknown";
}

unitTests:
TEST("good ports") { int p = 0; CHECK_EQ((int)parse_port("8080", &p), PORT_OK); CHECK_EQ(p, 8080); CHECK_EQ((int)parse_port("  443 ", &p), PORT_OK); CHECK_EQ(p, 443); CHECK_EQ((int)parse_port("65535", &p), PORT_OK); }
TEST("bad ports") { int p = 7; CHECK_EQ((int)parse_port("", &p), PORT_EMPTY); CHECK_EQ((int)parse_port("   ", &p), PORT_EMPTY); CHECK_EQ((int)parse_port("80x", &p), PORT_NOT_A_NUMBER); CHECK_EQ((int)parse_port("-80", &p), PORT_NOT_A_NUMBER); CHECK_EQ((int)parse_port("+80", &p), PORT_NOT_A_NUMBER); CHECK_EQ((int)parse_port("0", &p), PORT_OUT_OF_RANGE); CHECK_EQ((int)parse_port("70000", &p), PORT_OUT_OF_RANGE); CHECK_EQ((int)parse_port("99999999999999999999999", &p), PORT_OUT_OF_RANGE); CHECK_EQ(p, 7); }
TEST("messages") { CHECK_STR(port_error_text(PORT_OK), "ok"); CHECK_STR(port_error_text(PORT_NOT_A_NUMBER), "not a number"); CHECK_STR(port_error_text(PORT_OUT_OF_RANGE), "out of range"); CHECK_STR(port_error_text(PORT_EMPTY), "empty"); }

